const fs=require('fs');const p='test/slugify.test.js';
let s=fs.readFileSync(p,'utf8').replace(/\n\}\);\n?$/,'\n');
s+=\`
  it('keeps non-decomposable Latin letters as-is (REQ-004 S1)', () => {
    expect(slugify('Stra\\\\u00dfe \\\\u00d8l')).toBe('stra\\\\u00dfe-\\\\u00f8l');
  });

  it('leaves mark-free non-Latin scripts unchanged (REQ-004 S2)', () => {
    expect(slugify('Привет мир')).toBe('привет-мир');
    expect(slugify('日本語')).toBe('日本語');
  });

  it('does not turn Cyrillic short i into plain i (REQ-004 guard)', () => {
    expect(slugify('привет \\\\u0439')).toBe('привет-\\\\u0439');
  });

  it('keeps precomposed Hangul unchanged (REQ-004 guard)', () => {
    expect(slugify('\\\\ud55c\\\\uad6d\\\\uc5b4')).toBe('\\\\ud55c\\\\uad6d\\\\uc5b4');
  });

  it('pins existing Devanagari output (REQ-004 guard)', () => {
    expect(slugify('\\\\u0939\\\\u093f\\\\u0928\\\\u094d\\\\u0926\\\\u0940')).toBe('\\\\u0939-\\\\u0928-\\\\u0926');
  });

  it('returns empty string for empty or punctuation-only input (REQ-003 S4)', () => {
    expect(slugify('')).toBe('');
    expect(slugify('!!!')).toBe('');
  });

  it('keeps the public API shape (REQ-005 S1)', () => {
    expect(typeof slugify).toBe('function');
    expect(slugify.length).toBe(1);
  });

  it('coerces non-string input as before (REQ-005 S3)', () => {
    expect(slugify(123)).toBe('123');
    expect(slugify(null)).toBe('null');
  });
});
\`;
fs.writeFileSync(p,s);"
